import{c as t,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Beyond the Strongest LLM: Multi-Turn Multi-Agent Orchestration vs. Single LLMs on Benchmarks","description":"","frontmatter":{"url":"https://arxiv.org/abs/2509.23537","title":"Beyond the Strongest LLM: Multi-Turn Multi-Agent Orchestration vs. Single LLMs on Benchmarks","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2509.23537,"authors":["Aaron Xuxiang Tian","Ruofan Zhang","Jiayao Tang","Young Min Cho","Xueqian Li","Qiang Yi","Ji Wang","Zhunping Zhang","Danrui Qi","Zekun Li","Xingyu Xiang","Sharath Chandra Guntuku","Lyle Ungar","Tianyu Shi","Chi Wang"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2509.23537v1","pdf_path":"pdfs/2509.23537.pdf","published_date":"2025-09-28T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-09-28-multi-turn-multi-agent-orchestration-vs-single-llm-2509-23537.md","filePath":"research/papers/2025-09-28-multi-turn-multi-agent-orchestration-vs-single-llm-2509-23537.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-09-28-multi-turn-multi-agent-orchestration-vs-single-llm-2509-23537.md"};function s(i,e,l,h,g,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="beyond-the-strongest-llm-multi-turn-multi-agent-orchestration-vs-single-llms-on-benchmarks" tabindex="-1">Beyond the Strongest LLM: Multi-Turn Multi-Agent Orchestration vs. Single LLMs on Benchmarks <a class="header-anchor" href="#beyond-the-strongest-llm-multi-turn-multi-agent-orchestration-vs-single-llms-on-benchmarks" aria-label="Permalink to &quot;Beyond the Strongest LLM: Multi-Turn Multi-Agent Orchestration vs. Single LLMs on Benchmarks&quot;">​</a></h1><p><strong>Authors</strong>: Aaron Xuxiang Tian, Ruofan Zhang, Jiayao Tang, Young Min Cho, Xueqian Li, Qiang Yi, Ji Wang, Zhunping Zhang, Danrui Qi, Zekun Li, Xingyu Xiang, Sharath Chandra Guntuku, Lyle Ungar, Tianyu Shi, Chi Wang <strong>Published</strong>: September 28, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2509.23537" target="_blank" rel="noreferrer">https://arxiv.org/abs/2509.23537</a> · <a href="https://arxiv.org/html/2509.23537v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2509.23537 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2509.23537" target="_blank" rel="noreferrer">research/papers/pdfs/2509.23537.pdf</a> (9 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>We study multi-turn multi-agent orchestration, where multiple large language model (LLM) agents interact over multiple turns by iteratively proposing answers or casting votes until reaching consensus. Using four LLMs (Gemini 2.5 Pro, GPT-5, Grok 4, and Claude Sonnet 4) on GPQA-Diamond, IFEval, and MuSR, we conduct two experiments: (i) benchmarking orchestration against single-LLM baselines; and (ii) ablations on GPQA-Diamond that vary whether agents see who authored answers and whether they can observe ongoing votes. Orchestration matches or exceeds the strongest single model and consistently outperforms the others. Analysis of best-achievable orchestration performance shows potential for further gains. The ablations show that revealing authorship increases self-voting and ties, and that showing ongoing votes amplifies herding, which speeds convergence but can sometimes yield premature consensus.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>multi-turn multi-agent orchestration</strong> 框架：多個異質 LLM agent 跨多輪反覆「提案答案」或「投票」，直到達成 consensus。</li><li>以四個前沿 LLM（Gemini 2.5 Pro、GPT-5、Grok 4、Claude Sonnet 4）在三個 benchmark（GPQA-Diamond、IFEval、MuSR）上系統性對照 orchestration vs. single-LLM baseline。</li><li>在 GPQA-Diamond 上做兩組 ablation：(1) 是否揭露答案的 <strong>authorship</strong>（誰寫的）；(2) agent 是否能 <strong>觀察進行中的投票</strong>（ongoing votes）。</li><li>量化分析 best-achievable orchestration（上界）性能，揭示 orchestration 仍有未榨乾的提升空間。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Orchestration <strong>匹配或超越最強單一模型</strong>，並穩定優於其餘三個模型 —— 即「群體編排 &gt; 個別最強」。</li><li>Best-achievable 分析顯示：實際 orchestration 尚未觸頂，存在進一步增益潛力（方法層發現，原文未在 abstract 給單一數字）。</li><li>Ablation 發現的社會動力學偏差： <ul><li>揭露 <strong>authorship</strong> → 增加 <strong>self-voting</strong>（投自己）與 <strong>平票（ties）</strong>。</li><li>顯示 <strong>ongoing votes</strong> → 放大 <strong>herding（從眾）</strong>；加速收斂，但有時導致 <strong>premature consensus（過早定案）</strong>。</li></ul></li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（依 abstract 判斷）。可能弱點：</p><ul><li>僅三個 benchmark（GPQA-Diamond / IFEval / MuSR）、四個模型，泛化性與成本（多輪多模型 API 呼叫）未在 abstract 量化。</li><li>Premature consensus 與 herding 屬已觀察到的失敗模式，但 abstract 未提出穩健的緩解機制。</li><li>「best-achievable」為 oracle 式上界，與可實際落地的選票/收斂策略之間的差距未說明。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 Fan-out 假設</strong>：本文實證「多 agent 編排 ≥ 最強單模型」，為 <code>core.md §PROPOSE 委派</code> 的 fan-out 委派提供外部佐證。⚠️ 落地門檻：本文用四個<strong>異質前沿模型</strong>投票；workspace 多為<strong>同模型分工</strong>（Sonnet/Opus），群體多樣性增益未必等價。</li><li><strong>herding / premature consensus = multi-agent verdict 不可盡信</strong>：呼應 core.md TEST 的 <code>unverified_success</code> 閘門與 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的「subagent/workflow verdict 非證據，須機械重驗」。本文以實驗證明「觀察他人投票放大從眾」，正是該紀律要防的失敗模式。</li><li><strong>authorship 揭露 → self-voting/ties</strong>：對照 The Loop「child 不 self-resolve、矛盾交 parent」設計——隱藏作者身份可降低 self-preferential bias，與 dynamic-workflow 三失敗模式之一（self-preferential bias）吻合。⚠️ 本文情境為對等投票，與 workspace 的 parent↔child 階層拓撲不同，需審慎類比。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>可作為 advisor / <code>/pilot frontier</code> 稽核（原 quality-pipeline，v5.1 刪除） 多模型互審的理論背書</strong>：<code>/pilot frontier</code> 稽核 / <code>/pilot frontier</code> 稽核 的多模型 gate 設計與本文「orchestration 優於個別最強」一致；但須以本文的 premature-consensus 警告校準收斂條件，避免過早 gate-pass。</li></ul>',17)])])}const m=t(o,[["render",s]]);export{d as __pageData,m as default};
